-- Restore ten missing classic random-item reference definitions, not parent drop rates.
-- Numeric source data: AzerothCore/azerothcore-wotlk, commit
-- b704af465112832706b2c389b5cc9b9f5aad61cb, data/sql/base/db_world/reference_loot_template.sql
-- https://github.com/azerothcore/azerothcore-wotlk/blob/b704af465112832706b2c389b5cc9b9f5aad61cb/data/sql/base/db_world/reference_loot_template.sql
-- Adaptation: source LootMode=1 is its default loot mode; LoA derives loot mode
-- from map difficulty, so these generic choices use 0 (any difficulty).
-- All 650 item IDs were verified present and below the level-100 quarantine.
-- Existing definitions win as a WHOLE group. Reject a whole source group if an
-- item is unavailable/quarantined on another installation. Take a backup first.
CREATE TEMPORARY TABLE `codex_classic_ref_restore` (
 entry MEDIUMINT UNSIGNED NOT NULL,item MEDIUMINT NOT NULL,
 ChanceOrQuestChance FLOAT NOT NULL,lootmode INT UNSIGNED NOT NULL,
 groupid TINYINT UNSIGNED NOT NULL,mincountOrRef MEDIUMINT NOT NULL,
 maxcount SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(entry,item));
CREATE TEMPORARY TABLE `codex_existing_classic_refs` AS
 SELECT DISTINCT entry FROM `reference_loot_template`;
CREATE TEMPORARY TABLE `codex_unavailable_classic_refs` AS
 SELECT DISTINCT s.entry FROM `codex_classic_ref_restore` s
 LEFT JOIN `item_template` i ON i.entry=s.item
 WHERE i.entry IS NULL OR i.RequiredLevel>=100 OR i.name REGEXP 'TEST|DEPRECATED|UNUSED|PLACEHOLDER';
 SELECT s.entry,s.item,s.ChanceOrQuestChance,s.lootmode,s.groupid,s.mincountOrRef,s.maxcount
 FROM `codex_classic_ref_restore` s
 LEFT JOIN `codex_existing_classic_refs` e ON e.entry=s.entry
 LEFT JOIN `codex_unavailable_classic_refs` u ON u.entry=s.entry
 WHERE e.entry IS NULL AND u.entry IS NULL;
DROP TEMPORARY TABLE `codex_classic_ref_restore`;
DROP TEMPORARY TABLE `codex_existing_classic_refs`;
DROP TEMPORARY TABLE `codex_unavailable_classic_refs`;
